  'autonomy.title': 'مدى استقلالية {name}',
  'autonomy.intro': 'القرار لك من اليوم الأول. ومهما كان الاختيار: لا يُؤكَّد طلب من دونك، والأسعار من قواعد أسعارك فقط، وما تحجزه قواعدك يبقى بانتظارك.',
  'autonomy.disclosure': 'قبل الاختيار، معلومة مهمة: في الردود التي تُرسَل من دونك، تُخبر أولُ رسالة في المحادثة المشتري بأن الردّ ليس من إنسان، مع عرض التحدث مع شخص من فريقك. أما الردّ المُرسَل منك فلا يحمل هذه الجملة — لأنه منك.',
  'autonomy.needsName': 'مهما كان الاختيار هنا، سيبقى كل ردّ معروضًا عليك إلى حين تأكيد اسم {name} في صفحة التجهيز — فالرسالة المُرسَلة من دونك تحمل هذا الاسم إلى المشتري، ومن حقك قراءته أولًا.',
  'autonomy.notReleased': 'غير متاح بعد. جملة التعريف التي تُرسَل للمشتري لم يراجعها بعد متحدث أصلي بكل لغات الردود، ولا يخرج شيء من دونك قبل ذلك.',
