  'legal.updated': 'آخر تحديث: 17 سبتمبر 2026.',
  'legal.privacy.title': 'الخصوصية',
  'legal.privacy.intro': 'Nomi مساعدٌ تستخدمه الشركة للرد على من يكتب إليها عبر إنستغرام وفيسبوك ماسنجر وواتساب والبريد الإلكتروني. تشرح هذه الصفحة ما يُحفظ عند الكتابة إلى شركة تستخدمه، ولماذا، وكيفية طلب حذفه.',
  'legal.privacy.kept.title': 'ما الذي يُحفظ',
  'legal.privacy.kept.body': 'عند إرسال رسالة إلى شركة تستخدم Nomi، نحفظ الرسالة، وأي صورة أو ملف مرفق بها، والاسم الظاهر على حسابك، والمعرّف الذي تعطيه المنصة لحسابك، ووقت وصولها. وإذا راسلتك الشركة بالبريد الإلكتروني بموافقتك، يُحفظ عنوان بريدك والرسائل المتبادلة بالطريقة نفسها.',
  'legal.privacy.why.title': 'لماذا',
  'legal.privacy.why.body': 'لتتمكن الشركة من قراءة رسالتك والرد عليها. تُصاغ الردود بواسطة Nomi، وبحسب إعدادات الشركة قد لا تُرسل إلا بعد أن يوافق عليها شخص هناك. لا تُستخدم رسائلك للإعلان لك ولا تُباع.',
  'legal.privacy.who.title': 'من يطّلع عليها',
  'legal.privacy.who.body': 'الشركة التي وصلتها رسالتك، والخدمات اللازمة لنقل رسالتك والرد عليها:',
  'legal.privacy.who.meta': 'Meta، التي تنقل رسائل إنستغرام وماسنجر وواتساب بينك وبين الشركة.',
  'legal.privacy.ai': 'الردود هنا يصوغها مساعد ذكي، وبحسب إعدادات الشركة قد تصلك بعض الردود دون أن يراجعها شخص أولًا. ويمكنك طلب التحدث مع شخص في أي وقت أثناء المحادثة.',
  'legal.privacy.who.ai': '{processor}، خدمتها اللغوية تصوغ الردود من نص المحادثة. رسالتك تُعالَج هناك.',
  'legal.privacy.who.hosting': '{hosting}، مزوّد الاستضافة الذي تعمل عليه الخدمة. السجلات محفوظة هناك.',
  'legal.privacy.who.mail': 'وإذا ربطت الشركة صندوق بريد، فمزوّد البريد الذي تستخدمه (Google أو Microsoft) ينقل الرسائل الإلكترونية.',
  'legal.privacy.who.nobody': 'لا أحد غيرهم.',
